// 成员相关工具函数
const memberUtils = {
    setRoomMembers (roomId, members) {
        data_roomData.roomMembers[roomId] = members.map((member)=>({
                userId: member.userId,
                displayName: member.displayName || member.name || (typeof member.userId === 'string' ? member.userId.split('@')[0] : ''),
                avatarUrl: member.avatarUrl,
                membership: RoomMembership[(member.membership || '').toUpperCase()] || RoomMembership.LEAVE
            }));
    },
    getRoomMembers (roomId) {
        return data_roomData.roomMembers[roomId] || [];
    },
    updateMember (roomId, userId, updates// 允许其他属性
    ) {
        if (!data_roomData.roomMembers[roomId]) {
            data_roomData.roomMembers[roomId] = [];
        }
        const memberIndex = data_roomData.roomMembers[roomId].findIndex((m)=>m.userId === userId);
        if (memberIndex !== -1) {
            // 更新现有成员
            data_roomData.roomMembers[roomId][memberIndex] = {
                ...data_roomData.roomMembers[roomId][memberIndex],
                ...updates,
                membership: RoomMembership[(updates.membership || '').toUpperCase()] || RoomMembership.LEAVE
            };
        } else {
            // 添加新成员
            const { membership, ...restUpdates } = updates;
            data_roomData.roomMembers[roomId].push({
                userId,
                displayName: updates.displayName || (typeof userId === 'string' ? userId.split('@')[0] : ''),
                avatarUrl: updates.avatarUrl,
                membership: RoomMembership[(membership || '').toUpperCase()] || RoomMembership.LEAVE,
                ...restUpdates
            });
        }
    }
};

